import { test, expect } from '@playwright/test';

test.describe('Coupon Code Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message when coupon code is invalid', async ({ page }) => {
    // Intercept the API call to validate coupon code
    await page.route('**/api/checkout/validate-coupon', (route) => {
      route.abort('failed');
    });

    // Locate and fill the coupon input using getByLabel
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('INVALID123');

    // Locate and click the apply coupon button using getByRole
    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify error message is displayed using getByText
    const errorMessage = page.getByText('Invalid coupon code');
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific text
    await expect(errorMessage).toContainText('Coupon code is not valid');

    // Verify success message is not displayed
    const successMessage = page.getByText('Coupon applied successfully');
    await expect(successMessage).not.toBeVisible();

    // Verify coupon input is still visible
    await expect(couponInput).toBeVisible();
  });

  test('should display success message when coupon code is valid', async ({ page }) => {
    // Intercept the API call to validate coupon code
    await page.route('**/api/checkout/validate-coupon', (route) => {
      route.continue();
    });

    // Locate and fill the coupon input using getByLabel
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('SAVE10');

    // Locate and click the apply coupon button using getByRole
    const applyButton = page.getByRole('button', { name: /apply coupon/i });
    await applyButton.click();

    // Verify success message is displayed using getByText
    const successMessage = page.getByText('Coupon applied successfully');
    await expect(successMessage).toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText('Invalid coupon code');
    await expect(errorMessage).not.toBeVisible();

    // Verify coupon input is still visible
    await expect(couponInput).toBeVisible();
  });
});
